/* @lc app=leetcode id=966 lang=kotlin */ class Solution { fun spellchecker(wordlist: Array<String>, queries: Array<String>): Array<String> = wordlist.toSet().let { ex -> wordlist.reversed().associateBy { it.lowercase() }.let { cap -> wordlist.reversed().associateBy { it.lowercase().replace(Regex("[aeiou]"), "*") }.let { vow -> queries.map { q -> if (q in ex) q else cap[q.lowercase()] ?: vow[q.lowercase().replace(Regex("[aeiou]"), "*")] ?: "" }.toTypedArray() } } } }